mapper.select:
SELECT *
FROM
(
SELECT info.cash_id cashId,
info.finprod_id finprodId,
info.finprod_type finprodType,
info.cash_type_1 cashType1,
info.cash_type_1 cashType1Code,
info.cash_type_2 cashType2,
info.cash_type_2 cashType2Code,
DATE_FORMAT(crule.eff_date, '%Y-%m-%d') effDate,
crule.calc_type calcType,
crule.calc_type calcTypeCode,


crule.yield * 100 yield,
crule.basis,
crule.base_type baseType,
crule.base_type baseTypeCode,
crule.base_date_type baseDateType,
crule.base_date_type baseDateTypeCode,
prule.pay_cycle payCycle,
prule.pay_cycle payCycleCode,

prule.END_TDAY_RULE endTdayRule,
prule.END_TDAY_RULE endTdayRuleCode,
prule.PAY_TDAY_RULE payTdayRule,
prule.PAY_TDAY_RULE payTdayRuleCode,
prule.calc_rule calcRule,
prule.calc_rule calcRuleCode,
DATE_FORMAT(prule.first_pay_date, '%Y-%m-%d') firstPayDate,
prule.cash_unit_type cashUnitType,
prule.cash_unit_type cashUnitTypeCode,
prule.pay_type payType,
prule.pay_type payTypeCode,
crule.remark,
A.ACCR_TDAY_RULE as accrTdayRule,
 rn1,
 rn2
FROM FIN_CASH_INFO info
LEFT JOIN (
/* 子查询必加上rn字段 */
SELECT result.* FROM (
SELECT crule.*,
@rownum := @rownum + 1 row, /* 虚拟列行标 */
IF(
(
@CASH_ID = crule.CASH_ID and
@FINPROD_TYPE = crule.FINPROD_ID and
@FINPROD_TYPE = crule.FINPROD_TYPE
),
@rank := @rank + 1,
@rank := 1
) AS rn1, /* 分组虚拟列行标 */
/* 下面的分组条件需要与oracle中 over (PARTITION BY xxx,xxx,xxx)顺序保持一至 */
@CASH_ID := crule.CASH_ID /* 分组条件1 */
, @FINPROD_ID := crule.FINPROD_ID /* 分组条件2 */
, @FINPROD_TYPE := crule.FINPROD_TYPE /* 分组条件3 */
FROM (
/* 数据源 */
SELECT bc.*
FROM fin_cash_calc_rule bc
ORDER BY EFF_DATE ASC /* 按实际情况与oracle保持一至的排序 */
) crule,
/* 定义临时变量池 */
(SELECT @rownum := 0,
@CASH_ID := null,
@FINPROD_ID = null,
@FINPROD_TYPE = null,
@rank := 0) a
) result
) crule
ON info.cash_id = crule.cash_id
AND info.finprod_id = crule.finprod_id
AND info.finprod_type = crule.finprod_type
LEFT JOIN  (
/* 子查询必加上rn字段 */
SELECT result.* FROM (
SELECT prule.*,
@rownum := @rownum + 1 row, /* 虚拟列行标 */
IF(
(
@FINPROD_ID = prule.FINPROD_ID and
@FINPROD_TYPE = prule.FINPROD_TYPE and
@CASH_ID = prule.CASH_ID
),
@rank := @rank + 1,
@rank := 1
) AS rn2, /* 分组虚拟列行标 */
/* 下面的分组条件需要与oracle中 over (PARTITION BY xxx,xxx,xxx)顺序保持一至 */
@CASH_ID := prule.CASH_ID /* 分组条件1 */
, @FINPROD_ID := prule.FINPROD_ID /* 分组条件2 */
, @FINPROD_TYPE := prule.FINPROD_TYPE /* 分组条件3 */
FROM (
/* 数据源 */
SELECT bc.*
FROM fin_cash_pay_rule bc
ORDER BY EFF_DATE ASC
) prule,
/* 定义临时变量池 */
(SELECT @rownum := 0,
@CASH_ID := null,
@FINPROD_ID = null,
@FINPROD_TYPE = null,
@rank := 0) a
) result
) prule
ON info.cash_id = prule.cash_id
AND info.finprod_id = prule.finprod_id
AND info.finprod_type = prule.finprod_type
LEFT JOIN (
SELECT
CASH_ID,
ACCR_TDAY_RULE
from FIN_FLOAT_COUNTING_RULE
GROUP BY
CASH_ID,
ACCR_TDAY_RULE
) A
ON A.CASH_ID = info.CASH_ID
WHERE info.cash_type_1 = '03'

	AND info.FINPROD_id = #{finprodId}


	AND info.cash_type_2 = #{cashType2}


	AND info.cash_type_2 != #{noCashType2}

)
WHERE
rn1 = 1
AND rn2 = 1

select '' feeName, crule.base_type baseType, crule.basis basis, ffcr2.BASE_RULE calcRule, ffcr2.BASE_RULE calcRuleCode, DATE_FORMAT(ffcr.f_accr_date, '%Y-%m-%d') firCalculaDate, DATE_FORMAT(TMP.ACCR_END_DATE, '%Y-%m-%d') endCalculaDate, DATE_FORMAT(ffas.accr_str_date, '%Y-%m-%d') jtStrDate, DATE_FORMAT(ffas.accr_end_date, '%Y-%m-%d') jtEndDate, DATE_FORMAT(ffas.accr_date, '%Y-%m-%d') jtDate, C.LEV AS basicLevel, '' AS levelRemark, C.CHARGE_RATIO AS bankRatio, /* NVL2(C.CHARGE_RATIO, 1 - C.CHARGE_RATIO, '') AS customerRatio, */ IF(!ISNULL(C.CHARGE_RATIO) , 1 - C.CHARGE_RATIO , '' ), ffcr2.ACT_RULE actRule, prule.pay_type payType, prule.pay_type payTypeCode, ffcr.ACCR_TDAY_RULE accrTdayRule,
prule.END_TDAY_RULE endTdayRule, prule.END_TDAY_RULE endTdayRuleCode, prule.PAY_TDAY_RULE payTdayRule, prule.PAY_TDAY_RULE payTdayRuleCode, '' vdate, '' mdate, '' paydate from fin_cash_info fci left join fin_cash_calc_rule crule on fci.cash_id = crule.cash_id LEFT JOIN fin_cash_pay_rule prule ON crule.cash_id = prule.cash_id AND crule.EFF_DATE = prule.EFF_DATE LEFT JOIN FIN_FLOAT_COUNTING_RULE ffcr ON crule.cash_id = ffcr.cash_id AND crule.EFF_DATE = ffcr.EFF_DATE LEFT JOIN FIN_FLOAT_CALC_RULE_DETAIL C ON C.CASH_ID = ffcr.CASH_ID AND C.EFF_DATE = ffcr.EFF_DATE LEFT JOIN FIN_FLOAT_ACCRUAL_SCHE ffas ON ffas.cash_id = ffcr.cash_id LEFT JOIN FIN_FLOAT_CALC_RULE ffcr2 ON ffcr2.cash_id = ffcr.cash_id LEFT JOIN ( SELECT CASH_ID,MAX(ACCR_END_DATE) ACCR_END_DATE FROM FIN_FLOAT_ACCRUAL_SCHE GROUP BY CASH_ID ) TMP ON TMP.CASH_ID = fci.CASH_ID where 1=1
AND crule.finprod_id= #{finprodId}
AND fci.cash_type_2 = #{cashType2}
order by jtStrDate asc

select C.LEV AS basicLevel, /*业绩比较基准层级 */ '' AS levelRemark, /*层级描述 */ C.CHARGE_RATIO AS bankRatio, /*银行收取比例 */ IF(!ISNULL(C.CHARGE_RATIO) , 1 - C.CHARGE_RATIO , '' ) AS customerRatio /*客户分配比例 */ from fin_cash_info fci LEFT JOIN ( SELECT CASH_ID,MAX(EFF_DATE) MAX_EFF_DATE FROM FIN_FLOAT_CALC_RULE GROUP BY CASH_ID ) TMP ON TMP.CASH_ID = fci.CASH_ID LEFT JOIN FIN_FLOAT_CALC_RULE_DETAIL C ON C.CASH_ID = TMP.CASH_ID AND C.EFF_DATE = TMP.MAX_EFF_DATE where 1=1
AND fci.finprod_id= #{finprodId}
AND fci.cash_type_2 = #{cashType2}
order by C.LEV asc

select DATE_FORMAT(ffas.accr_str_date, '%Y-%m-%d') jtStrDate, DATE_FORMAT(ffas.accr_end_date, '%Y-%m-%d') jtEndDate, DATE_FORMAT(ffas.accr_date, '%Y-%m-%d') jtDate from fin_cash_info fci LEFT JOIN FIN_FLOAT_ACCRUAL_SCHE ffas ON ffas.cash_id = fci.cash_id where 1=1
AND fci.finprod_id= #{finprodId}
AND fci.cash_type_2 = #{cashType2}
order by ffas.accr_str_date asc
